    public function restored(): bool {return (bool)$this->query('select 1 from v_pbx_restore where domain_uuid=:d',['d'=>$this->domain])->fetchColumn();}
    public function config(bool $lock=false): array {$r=$this->query('select config from v_pbx_restore where domain_uuid=:d'.($lock?' for update':''),['d'=>$this->domain])->fetchColumn();if(!$r)throw new RuntimeException('Choose a restored PBX first.');return json_decode($r,true,512,JSON_THROW_ON_ERROR);}
    public function report(): array {$r=$this->query('select report from v_pbx_restore where domain_uuid=:d',['d'=>$this->domain])->fetchColumn();return $r?json_decode($r,true,512,JSON_THROW_ON_ERROR):[];}
    public function initialize(string $realm,string $timezone='UTC'): void {
        if(!$this->db->inTransaction())throw new LogicException('Initialization requires a transaction.');
        if($this->query('select domain_name from v_domains where domain_uuid=:d for update',['d'=>$this->domain])->fetchColumn()!==$realm)throw new InvalidArgumentException('Choose the active PBX address.');
        if($this->restored())throw new InvalidArgumentException('This PBX is already configured.');
        if(!preg_match('/^[a-z0-9.-]+$/D',$realm)||!in_array($timezone,DateTimeZone::listIdentifiers(),true))throw new InvalidArgumentException('Choose a valid PBX address and timezone.');
        if($this->query('select 1 from v_extensions where domain_uuid=:d limit 1',['d'=>$this->domain])->fetchColumn())throw new InvalidArgumentException('This PBX already has users.');
        $media=pbx_paths::media().'/'.$this->domain;if(!is_dir($media)&&!mkdir($media,0700,true))throw new RuntimeException('Private media storage is unavailable.');
        $config=['realm'=>$realm,'timezone'=>$timezone,'origin'=>'OpenWeb PBX','users'=>new stdClass,'trunks'=>new stdClass];
        foreach(['queues','ring_groups','receptionists','departments','inbound_rules','outbound_rules','phones','contacts','specials','scripts'] as $key)$config[$key]=[];
        $this->query("insert into v_pbx_restore(domain_uuid,source_version,config,report) values(:d,'OpenWeb PBX 1.0.2',cast(:c as jsonb),'{}')",['d'=>$this->domain,'c'=>json_encode($config,JSON_THROW_ON_ERROR)]);
