        $this->newDialplan('*97','voicemail_login',$config,'all');
    }
    public function services(): array {return $this->query('select s.domain_uuid,s.service_name,t.tenant_name from v_pbx_services s join v_pbx_tenants t on t.tenant_uuid=s.tenant_uuid join v_domains sd on sd.domain_uuid=s.domain_uuid where t.owner_user_uuid=:u and t.enabled and sd.domain_enabled order by s.created_at',['u'=>$_SESSION['user_uuid']])->fetchAll(PDO::FETCH_ASSOC);}
    public static function openPreferred(): void {
        $setup=new pbx_setup;if(!$setup->canManage())return;$db=database::new()->db;
        $s=$db->prepare('select domain_name from v_domains where domain_uuid=:d');$s->execute(['d'=>$_SESSION['domain_uuid']]);if($s->fetchColumn()!==pbx_paths::host())return;
        $s=$db->prepare('select s.domain_uuid from v_pbx_services s join v_pbx_tenants t on t.tenant_uuid=s.tenant_uuid join v_pbx_restore r on r.domain_uuid=s.domain_uuid join v_domains sd on sd.domain_uuid=s.domain_uuid where t.owner_user_uuid=:u and t.enabled and sd.domain_enabled order by r.restored_at desc limit 1');$s->execute(['u'=>$_SESSION['user_uuid']]);$d=$s->fetchColumn();if($d)$setup->switchDomain($d);
