        foreach($this->config()['users'] as $number=>$u){$cache->delete('directory:'.$u['auth_id'].'@'.$realm);$cache->delete('directory:'.$number.'@'.$realm);}
        try{event_socket::api('reloadxml');if($trunk&&is_uuid($trunk)){event_socket::api('sofia profile external killgw '.$trunk);event_socket::api('sofia profile external rescan');}if($queue&&preg_match('/^[0-9]{2,10}$/D',$queue))event_socket::api('callcenter_config queue unload '.$queue.'@'.$realm);}catch(Throwable){error_log('OpenWeb PBX: call settings saved; reload unavailable');}
    }
    private function row(array $rows,string $key,string $field='number'): array {foreach($rows as $i=>$r)if((string)$r[$field]===$key)return [$i,$r];throw new InvalidArgumentException('This item is not in your PBX.');}
    public function destinations(array $config): array {
        $out=['None:'=>'End Call'];foreach($config['users'] as $n=>$u){$out['Extension:'.$n]=$n.' · '.$u['name'];if($u['voicemail_enabled'])$out['VoiceMail:'.$n]=$n.' · '.$u['name'].' · Voicemail';}
        foreach(['queues'=>'Queue','ring_groups'=>'RingGroup','receptionists'=>'IVR','scripts'=>'RoutePoint'] as $key=>$kind)foreach($config[$key] as $r)$out[$kind.':'.$r['number']]=$r['number'].' · '.$r['name'];$out['External:']='External Number';return $out;
    }
    private function destination(array $in,string $key,array $config,array $fallback=['type'=>'None','number'=>'','external'=>'']): array {
        if(!isset($in[$key]))return $fallback;$value=$this->text($in,$key,50);$choices=$this->destinations($config);if(!isset($choices[$value]))throw new InvalidArgumentException('Choose a call destination.');[$type,$number]=explode(':',$value,2);$external='';if($type==='External')$external=$this->number($in,$key.'_external');return ['type'=>$type,'number'=>$number,'external'=>$external];
    }
    private function selectedUsers(array $in,string $key,array $config): array {$rows=$in[$key]??[];if(!is_array($rows)||count($rows)>1000)throw new InvalidArgumentException('Choose users from this PBX.');$out=[];foreach($rows as $n){if(!is_string($n)||!isset($config['users'][$n]))throw new InvalidArgumentException('Choose users from this PBX.');$out[$n]=['number'=>$n,'status'=>'LoggedIn','skill'=>'0'];}return array_values($out);}
