        $this->db->beginTransaction();try{$c=$this->config(true);$result=match($type){'user'=>$this->saveUser($key,$in,$c),'trunk'=>$this->saveTrunk($key,$in,$c),'department'=>$this->saveDepartment($key,$in,$c),'hours'=>$this->saveHours($key,$in,$c),'queue','ring_group','receptionist'=>$this->saveHandling($type,$key,$in,$c),'outbound'=>$this->saveOutbound($key,$in,$c),'incoming'=>$this->saveIncoming($key,$in,$c),'script'=>$this->saveScript($key,$in,$c),default=>throw new InvalidArgumentException('Choose an admin page.')};$this->saveConfig($c);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}$this->changed($type==='trunk'?$this->config()['trunks'][$result]['gateway_uuid']:null,$type==='queue'?$result:null);return $result;
